import{_ as t,o as a,c as r,ak as s}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy testing and evaluation","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","frontmatter":{"title":"Chainy testing and evaluation","description":"Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the adoption archive.","source":"docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.md","category":"Archive","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.md","filePath":"content/docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.md"}'),o={name:"content/docs/archive/pre-v2-adoption-2026-10-23/docs/qa-evaluation.md"};function n(i,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<div><h1 id="chainy-testing-and-evaluation">Chainy testing and evaluation<a class="header-anchor" href="#chainy-testing-and-evaluation" aria-label="Link to this section">​</a></h1><blockquote><p>Historical snapshot taken before v2 adoption on October 23, 2026. Not active requirements or current progress. See the <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/readme.html">adoption archive</a>.</p></blockquote><p>Owners: Christian (technical review), Miguel (test execution), Sean (research), Sherwin (site/readiness), Luis (visual checks). October 12, 2026.</p><h2 id="game-test-checklist">Game test checklist<a class="header-anchor" href="#game-test-checklist" aria-label="Link to this section">​</a></h2><p>All results are <strong>Not verified in this documentation review</strong>. Christian&#39;s implementation report is evidence of reported progress, not a replacement for these checks.</p><table><thead><tr><th>Check</th><th>Expected result</th><th>Task</th></tr></thead><tbody><tr><td>Offline install/start</td><td>Named Android build installs and starts without internet</td><td>CH-03/14</td></tr><tr><td>Profile separation</td><td>Two learners on one phone retain separate records; switching clears old UI</td><td>CH-04/26</td></tr><tr><td>Movement and scenes</td><td>Movement/collision/interactions work; loading failures return to a usable screen</td><td>CH-05/14</td></tr><tr><td>Quiz</td><td>Correct/incorrect responses, score, attempts, finish and retry follow approved rules</td><td>CH-06</td></tr><tr><td>Wordle</td><td>Valid/invalid guesses, repeated letters, win/loss and attempt limits follow approved rules</td><td>CH-08</td></tr><tr><td>BlockMatch</td><td>Legal/illegal moves, cascades, objectives and no-move/end states behave correctly</td><td>CH-07</td></tr><tr><td>Save/reload</td><td>Result persists; failed save gives feedback; repeating a save does not count twice</td><td>CH-04/06</td></tr><tr><td>Pause/interruption</td><td>No duplicate inputs or mixed profiles; relaunch uses a supported saved point</td><td>CH-14</td></tr><tr><td>Content and UI</td><td>Accurate explanations, readable controls, non-color cues and audio-off instructions</td><td>CH-09/10/26</td></tr><tr><td>Collection</td><td>Approved data exports; cancel/failure preserves records; duplicate collection is detected</td><td>CH-11</td></tr><tr><td>Update</td><td>Tested signed update preserves existing records</td><td>CH-14</td></tr><tr><td>Full session</td><td>All required modes work on the beta device without a core-blocking/data-loss defect</td><td>CH-13/14</td></tr></tbody></table><p>For each check record <strong>build + device + steps + expected result + actual result + evidence + reviewer</strong>. Use synthetic data for internal testing.</p><p>A core-blocking defect prevents startup, saving or a required activity. Data loss and wrong scoring/learning feedback need correction before using the affected build with learners. Cosmetic issues can be listed separately.</p><h2 id="beta-readiness">Beta readiness<a class="header-anchor" href="#beta-readiness" aria-label="Link to this section">​</a></h2><p>The beta is fixed for <strong>November 3–6, 2026 at Tambunan National High School, Marinduque</strong>. The integrated candidate target is October 30; October 31–November 2 is protected for readiness checks.</p><p>Christian confirms the build and records are ready. Sean confirms instruments and evidence handling. Sherwin confirms site arrangements, devices and required permissions. If any is missing, record the blocker and resolve it with the responsible school/team contact; do not claim the fixed date establishes approval.</p><h2 id="learner-evaluation">Learner evaluation<a class="header-anchor" href="#learner-evaluation" aria-label="Link to this section">​</a></h2><p>Sean follows the school-approved procedure and confirms respondent details, sampling, instruments and any participant/guardian requirements. Sample size, session duration and the precise school “ISO 2010” instrument are still unknown.</p><p>Recommended sequence, subject to the approved protocol:</p><ol><li>Explain the session and select the correct learner profile.</li><li>Collect the approved pre-assessment if the study measures change.</li><li>Give consistent control instructions; record assistance and interruptions.</li><li>Play the agreed learning content and collect the approved post-assessment/usability feedback.</li><li>Check that records were collected successfully and prepare the device for the next learner.</li></ol><p>In-game Quiz/Wordle/BlockMatch performance is not automatically a validated learning measure. Repeated practice scores and independent evaluation scores must be described separately.</p><h2 id="results-and-defense">Results and defense<a class="header-anchor" href="#results-and-defense" aria-label="Link to this section">​</a></h2><p>Sean reports actual participant/paired counts, missing records, observed scores and feedback, with methods and limitations. Do not infer learning gains from game completion or write results before collection. An observed pre/post difference alone does not prove the game caused the change.</p><p>Use November 7–13 for evidence review, analysis and fixes; November 14–16 for manuscript assembly; November 17–20 for rehearsal. <strong>Pre-final is November 21, 2026.</strong> The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/manuscript-evidence-map.html">official evidence map</a> remains the school submission checklist.</p></div>',1)])])}const v=t(o,[["render",n]]);export{u as __pageData,v as default};
